public class QuotedPrintableCodec_decodeQuotedPrintable_TriageGen1Test {







    @Test
    public void testDecodeQuotedPrintable_MixedContent() throws DecoderException {
        // "A=3D B" -> "A= B" (if =3D is decoded)
        // Let's test: "Hello=20World" -> "Hello World"
